// KB V1 sin RAG: la colección es pequeña, se devuelve entera y responde el agente.
// El texto va TAL CUAL: horarios, precios y condiciones no se resumen ni se reinterpretan.
//
// Y detrás, la lista de servicios que se pueden RESERVAR, leída de `services`. La KB la
// escribe una persona y no se entera de un servicio nuevo: con solo la KB, Lucía contestó
// "no ofrecemos demo" teniendo el servicio creado y activo (2/oct/2026). Lo que se puede
// reservar lo dice la tabla con la que reserva el Booking API, no un texto.
// Se leen por nombre de nodo, no por $json: son dos consultas en cadena.
const leer = (nombre) => {
  const r = $(nombre).first().json ?? {};
  const code = r.statusCode ?? 0;
  const body = (r.body ?? r) || {};
  if (code >= 300 || body.errors) return { error: JSON.stringify(body.errors || body).slice(0, 300) };
  return { rows: Array.isArray(body.data) ? body.data : [] };
};

const kb = leer('HTTP · Directus knowledge');
if (kb.error) return [{ json: { ok: false, motivo: 'error_kb', detalle: kb.error } }];
const sv = leer('HTTP · Directus servicios');

const partes = kb.rows.map(x => '## ' + (x.title || '') + '\n' + (x.body || ''));
const servicios = sv.rows || [];
if (servicios.length) {
  partes.push('## Servicios que se pueden reservar\n' + servicios.map(s =>
    '- ' + s.name + (s.duration_minutes ? ` (${s.duration_minutes} min)` : '') +
    (s.description ? ': ' + String(s.description).trim() : '')).join('\n'));
}

const texto = partes.join('\n\n');
return [{ json: {
  ok: true,
  hay_info: texto.length > 0,
  texto,
  // Si la lista de servicios no se pudo leer, que se note: decir "no lo ofrecemos" sobre
  // una consulta fallida es el mismo error que esto viene a quitar.
  ...(sv.error ? { aviso: 'No se pudo leer la lista de servicios.' } : {}),
} }];
